// Shared BCS data core moved to storageBCS/storageBCS_core.js
function __tryRestoreTempNodesFromBcs() {
    if (__canvasTempStateBcsLoadInProgress) return true;
    __canvasTempStateBcsLoadInProgress = true;

    Promise.resolve()
        .then(async () => {
            const state = await __loadCanvasTempStateFromBcs();
            __canvasTempStateBcsLoadInProgress = false;

            if (state) {
                __applyCanvasTempStateObject(state);
                __finalizeTempNodesLoad({ loadedFromStorage: true });
                return;
            }

            CanvasState.tempSections = [];
            const demoTemplate = createInitialDemoTemplate();
            CanvasState.mdNodes = demoTemplate.mdNodes;
            CanvasState.mdNodeCounter = demoTemplate.mdNodeCounter;
            CanvasState.edges = demoTemplate.edges;
            CanvasState.edgeCounter = demoTemplate.edgeCounter;
            console.log('[Canvas] 首次使用，加载演示模板');
            __finalizeTempNodesLoad({ loadedFromStorage: false });
        })
        .catch((e) => {
            __canvasTempStateBcsLoadInProgress = false;
            console.warn('[Canvas] 读取 BCS 失败:', e);

            CanvasState.tempSections = [];
            const demoTemplate = createInitialDemoTemplate();
            CanvasState.mdNodes = demoTemplate.mdNodes;
            CanvasState.mdNodeCounter = demoTemplate.mdNodeCounter;
            CanvasState.edges = demoTemplate.edges;
            CanvasState.edgeCounter = demoTemplate.edgeCounter;
            console.log('[Canvas] 首次使用，加载演示模板');
            __finalizeTempNodesLoad({ loadedFromStorage: false });
        });

    return true;
}

function __getCanvasStorageOnChangedArea() {
    try {
        if (typeof browserAPI !== 'undefined' && browserAPI && browserAPI.storage && browserAPI.storage.onChanged) {
            return browserAPI.storage.onChanged;
        }
    } catch (_) { }
    try {
        if (typeof chrome !== 'undefined' && chrome && chrome.storage && chrome.storage.onChanged) {
            return chrome.storage.onChanged;
        }
    } catch (_) { }
    try {
        if (typeof browser !== 'undefined' && browser && browser.storage && browser.storage.onChanged) {
            return browser.storage.onChanged;
        }
    } catch (_) { }
    return null;
}

function __extractCanvasTempStateTimestamp(state) {
    const ts = Number(state && state.timestamp);
    return Number.isFinite(ts) && ts > 0 ? ts : 0;
}

function __hasCanvasTempStatePayloadShape(state) {
    return !!(
        state
        && typeof state === 'object'
        && (
            Array.isArray(state.sections)
            || Array.isArray(state.tempSections)
            || Array.isArray(state.mdNodes)
            || Array.isArray(state.cards)
            || Array.isArray(state.edges)
        )
    );
}

function __normalizeCanvasTempStateForRuntime(stateInput, options = {}) {
    const parsedState = typeof stateInput === 'string'
        ? __safeParseCanvasStorageJson(stateInput)
        : stateInput;
    if (!__hasCanvasTempStatePayloadShape(parsedState)) return null;
    const preserveRaw = !!(options && options.preserveRaw === true);

    const sections = Array.isArray(parsedState.sections)
        ? parsedState.sections
        : (Array.isArray(parsedState.tempSections) ? parsedState.tempSections : []);
    const mdNodes = Array.isArray(parsedState.mdNodes)
        ? parsedState.mdNodes
        : (Array.isArray(parsedState.cards) ? parsedState.cards : []);
    const edges = Array.isArray(parsedState.edges) ? parsedState.edges : [];

    if (preserveRaw) {
        return {
            ...parsedState,
            sections: sections.map((section) => __cloneCanvasProtocolJson(section)).filter(Boolean),
            tempSectionCounter: Number(parsedState.tempSectionCounter) || sections.length || 0,
            tempItemCounter: Number(parsedState.tempItemCounter) || 0,
            colorCursor: Number(parsedState.colorCursor) || 0,
            tempSectionLastColor: parsedState.tempSectionLastColor || getTempSectionDefaultColor(),
            tempSectionPrevColor: parsedState.tempSectionPrevColor || null,
            mdNodes: mdNodes.map((node) => __cloneCanvasProtocolJson(node)).filter(Boolean),
            mdNodeCounter: Number(parsedState.mdNodeCounter) || mdNodes.length || 0,
            edges: edges.map((edge) => __cloneCanvasProtocolJson(edge)).filter(Boolean),
            edgeCounter: Number(parsedState.edgeCounter) || edges.length || 0,
            timestamp: Number(parsedState.timestamp) || Date.now()
        };
    }

    return __buildCanvasTempStateProtocolView({
        ...parsedState,
        sections,
        tempSectionCounter: Number(parsedState.tempSectionCounter) || sections.length || 0,
        tempItemCounter: Number(parsedState.tempItemCounter) || 0,
        colorCursor: Number(parsedState.colorCursor) || 0,
        tempSectionLastColor: parsedState.tempSectionLastColor || getTempSectionDefaultColor(),
        tempSectionPrevColor: parsedState.tempSectionPrevColor || null,
        mdNodes,
        mdNodeCounter: Number(parsedState.mdNodeCounter) || mdNodes.length || 0,
        edges,
        edgeCounter: Number(parsedState.edgeCounter) || edges.length || 0,
        timestamp: Number(parsedState.timestamp) || Date.now()
    });
}

function __isCanvasTempStatePayload(state) {
    return !!__normalizeCanvasTempStateForRuntime(state);
}

function __applyCanvasTempStateRealtimeSyncNow(state, source = 'external', options = {}) {
    const normalizedState = __normalizeCanvasTempStateForRuntime(state);
    if (!normalizedState) return;

    const ts = __extractCanvasTempStateTimestamp(normalizedState);
    if (ts > 0) {
        if (ts <= __canvasTempStateLastAppliedTimestamp) return;
        if (ts <= __canvasTempStateLastSavedTimestamp) return;
    }

    if (__canvasTempStateRealtimeSyncApplying) return;

    const maximizeDescriptor = __getActiveMaximizedNodeDescriptor();
    const shouldEnableFullscreenGuard = !!maximizeDescriptor;
    if (shouldEnableFullscreenGuard) {
        CanvasState.pendingMaximizedDescriptor = maximizeDescriptor;
        CanvasState.maximizedNodeRemovalObserverMuted = true;
    }

    __canvasTempStateRealtimeSyncApplying = true;
    try {
        __resetCanvasDomAndStateForImport();
        __applyCanvasTempStateObject(normalizedState);
        __finalizeTempNodesLoad({ loadedFromStorage: true });
        if (options && options.bcsStorage) {
            try {
                __applyPermanentLayoutFromBcsStorageSnapshot(options.bcsStorage, { removeMissingCopies: true });
            } catch (_) { }
        }

        if (ts > 0) {
            __canvasTempStateLastAppliedTimestamp = Math.max(__canvasTempStateLastAppliedTimestamp, ts);
        }

        console.log('[Canvas] 已同步外部画布状态:', source, ts || 'no-ts');
    } catch (error) {
        console.warn('[Canvas] 外部画布状态同步失败:', error);
    } finally {
        __canvasTempStateRealtimeSyncApplying = false;
        if (shouldEnableFullscreenGuard) {
            const releaseGuard = () => {
                CanvasState.maximizedNodeRemovalObserverMuted = false;
            };
            if (typeof requestAnimationFrame === 'function') {
                requestAnimationFrame(releaseGuard);
            } else {
                setTimeout(releaseGuard, 16);
            }
        }
    }
}

function __queueCanvasTempStateRealtimeSync(state, source = 'external', options = {}) {
    const normalizedState = __normalizeCanvasTempStateForRuntime(state);
    if (!normalizedState) return;

    const normalizedOptions = (options && typeof options === 'object') ? options : {};
    __canvasTempStateRealtimeSyncPending = { state: normalizedState, source, options: normalizedOptions };
    if (__canvasTempStateRealtimeSyncTimer) return;

    __canvasTempStateRealtimeSyncTimer = setTimeout(() => {
        __canvasTempStateRealtimeSyncTimer = null;
        const pending = __canvasTempStateRealtimeSyncPending;
        __canvasTempStateRealtimeSyncPending = null;
        if (!pending || !pending.state) return;
        __applyCanvasTempStateRealtimeSyncNow(pending.state, pending.source, pending.options || {});
    }, 140);
}

function __consumeCanvasTempStateRealtimeSignal(rawState, source = 'external') {
    if (!rawState || typeof rawState !== 'object') return;

    if (__isCanvasTempStateBcsMarker(rawState)) {
        __loadCanvasTempStateBundleFromBcs()
            .then((bundle) => {
                if (!bundle || !bundle.state) return;
                __queueCanvasTempStateRealtimeSync(bundle.state, `${source}:bcs-marker`, {
                    bcsStorage: bundle.storage
                });
            })
            .catch(() => { });
        return;
    }

    const normalizedState = __normalizeCanvasTempStateForRuntime(rawState);
    if (!normalizedState) return;
    __queueCanvasTempStateRealtimeSync(normalizedState, source);
}

function __safeParseCanvasStorageJson(raw) {
    if (typeof raw !== 'string' || !raw) return null;
    try {
        return JSON.parse(raw);
    } catch (_) {
        return null;
    }
}

function __applyPermanentSectionCopiesRealtimeSync(rawValue) {
    const parsed = __safeParseCanvasStorageJson(rawValue);
    const copies = Array.isArray(parsed) ? parsed.filter(Boolean) : [];
    try { __writePermanentSectionCopies(copies); } catch (_) { }
    __syncPermanentLayoutFromBcsCanvasAsync({ removeMissingCopies: true });
}

function __applyCanvasAppearanceRealtimeSync(rawValue) {
    if (typeof rawValue !== 'string' || !rawValue) return;
    const parsed = __safeParseCanvasStorageJson(rawValue);
    if (!parsed || typeof parsed !== 'object') return;

    const normalized = normalizeCanvasAppearanceSettings(parsed);
    CanvasState.appearanceSettings = normalized;

    try { applyCanvasAppearanceSettings(normalized, { applyPermanentSize: false }); } catch (_) { }
    try { applyTempSectionAutoSizeAll(); } catch (_) { }
    try {
        if (window.CanvasSidebarDirectory && typeof window.CanvasSidebarDirectory.refresh === 'function') {
            window.CanvasSidebarDirectory.refresh({ force: true });
        }
    } catch (_) { }
}

function __applyCanvasOtherSettingsRealtimeSync(rawValue) {
    if (typeof rawValue !== 'string' || !rawValue) return;
    const parsed = __safeParseCanvasStorageJson(rawValue);
    if (!parsed || typeof parsed !== 'object') return;

    const prevSettings = normalizeCanvasOtherSettings(getCanvasOtherSettings());
    const normalized = normalizeCanvasOtherSettings(parsed);
    CanvasState.otherSettings = normalized;

    const prevFollow = isTempColorFollowEnabled(prevSettings);
    const nextFollow = isTempColorFollowEnabled(normalized);
    if (prevFollow !== nextFollow) {
        try { __applyGlobalTempColorFollowSetting(nextFollow); } catch (_) { }
    }

    try {
        window.dispatchEvent(new CustomEvent('canvas-other-settings-updated', { detail: normalized }));
    } catch (_) { }
    try {
        if (window.CanvasSidebarDirectory && typeof window.CanvasSidebarDirectory.refresh === 'function') {
            window.CanvasSidebarDirectory.refresh({ force: true });
        }
    } catch (_) { }
}

const PERMANENT_TIP_TIMESTAMP_KEY_PREFIX = 'canvas-permanent-tip-updated-at:';
const __permanentTipLastAppliedTimestamp = new Map();

function __buildPermanentTipTimestampStorageKey(storageKey) {
    if (typeof storageKey !== 'string' || !storageKey) return '';
    return `${PERMANENT_TIP_TIMESTAMP_KEY_PREFIX}${storageKey}`;
}

function __readPermanentTipTimestamp(storageKey) {
    const timestampKey = __buildPermanentTipTimestampStorageKey(storageKey);
    if (!timestampKey) return 0;
    try {
        const raw = localStorage.getItem(timestampKey);
        const parsed = parseInt(raw, 10);
        return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
    } catch (_) {
        return 0;
    }
}

function __writePermanentTipTimestamp(storageKey, timestamp = null) {
    const timestampKey = __buildPermanentTipTimestampStorageKey(storageKey);
    if (!timestampKey) return 0;

    const ts = (Number.isFinite(Number(timestamp)) && Number(timestamp) > 0)
        ? Number(timestamp)
        : Date.now();

    try {
        saveSharedState(timestampKey, String(ts), { asJSON: false });
    } catch (_) { }

    const prev = Number(__permanentTipLastAppliedTimestamp.get(storageKey) || 0);
    if (ts > prev) {
        __permanentTipLastAppliedTimestamp.set(storageKey, ts);
    }

    return ts;
}

function __shouldApplyPermanentTipRealtimeSync(storageKey) {
    if (typeof storageKey !== 'string' || !storageKey) return false;

    const nextTs = __readPermanentTipTimestamp(storageKey);
    if (nextTs <= 0) return true;

    const lastTs = Number(__permanentTipLastAppliedTimestamp.get(storageKey) || 0);
    if (lastTs > 0 && nextTs < lastTs) {
        return false;
    }

    __permanentTipLastAppliedTimestamp.set(storageKey, Math.max(lastTs, nextTs));
    return true;
}

function __persistPermanentTipStorageValue(storageKey, value, options = {}) {
    if (typeof storageKey !== 'string' || !storageKey) return;

    const parsedKey = __parsePermanentTipStorageKey(storageKey);
    let persistedValue = value;
    if (parsedKey && parsedKey.type === 'content') {
        const source = String(value == null ? '' : value);
        const preserveRawContent = !!(options && options.preserveRawContent === true);
        persistedValue = preserveRawContent
            ? source
            : __normalizePermanentViewDescriptionMarkdown(source);
    }

    const ts = __writePermanentTipTimestamp(storageKey, Date.now());
    try {
        if (typeof persistedValue === 'string' && persistedValue) {
            saveSharedState(storageKey, persistedValue, { asJSON: false });
        } else {
            localStorage.removeItem(storageKey);
        }
    } catch (_) { }

    const prev = Number(__permanentTipLastAppliedTimestamp.get(storageKey) || 0);
    if (ts > prev) {
        __permanentTipLastAppliedTimestamp.set(storageKey, ts);
    }
}


function __parsePermanentTipStorageKey(key) {
    if (typeof key !== 'string' || !key) return null;

    if (key === PERMANENT_MAIN_TIP_STORAGE_KEY) {
        return { type: 'content', copyId: null };
    }
    if (key === `${PERMANENT_MAIN_TIP_STORAGE_KEY}-font-size`) {
        return { type: 'font-size', copyId: null };
    }

    const copyPrefix = PERMANENT_COPY_TIP_STORAGE_PREFIX;
    if (!key.startsWith(copyPrefix)) return null;

    let tail = key.slice(copyPrefix.length);
    if (!tail) return null;

    let type = 'content';
    const fontSizeSuffix = '-font-size';
    if (tail.endsWith(fontSizeSuffix)) {
        type = 'font-size';
        tail = tail.slice(0, -fontSizeSuffix.length);
    }
    if (!tail) return null;

    return { type, copyId: tail };
}

function __findPermanentTipSectionByStorageKey(parsed) {
    if (!parsed || typeof parsed !== 'object') return null;

    if (!parsed.copyId) {
        return document.getElementById('permanentSection');
    }

    const canvasContent = document.getElementById('canvasContent');
    const scope = canvasContent || document;
    const candidates = scope.querySelectorAll('.permanent-bookmark-section.permanent-section-copy');
    for (const sectionEl of candidates) {
        if (!sectionEl || !sectionEl.dataset) continue;
        if (sectionEl.dataset.permanentSectionCopyId === parsed.copyId) {
            return sectionEl;
        }
    }
    return null;
}

function __applyPermanentTipContentRealtimeSync(sectionEl, rawValue) {
    if (!sectionEl) return;

    const tipText = sectionEl.querySelector('.permanent-section-tip');
    if (!tipText) return;

    const editable = String(tipText.contentEditable || '').toLowerCase();
    if (editable === 'true') return;

    const source = (typeof rawValue === 'string') ? rawValue : '';
    const normalized = __normalizeCanvasRichHtml(__coerceDescriptionSourceToHtml(source));

    tipText.innerHTML = normalized;
    try { __applyHeadingCollapse(tipText); } catch (_) { }

    const lang = typeof currentLang !== 'undefined' ? currentLang : 'zh_CN';
    const isEn = lang === 'en' || lang === 'en_US' || lang === 'en-GB' || String(lang).toLowerCase().startsWith('en');
    tipText.title = normalized
        ? (isEn ? 'Click to edit' : '点击编辑说明')
        : (isEn ? 'Click to add description' : '点击添加说明');
}

function __applyPermanentTipFontSizeRealtimeSync(sectionEl, rawValue) {
    if (!sectionEl) return;

    const tipText = sectionEl.querySelector('.permanent-section-tip');
    if (!tipText) return;

    const editable = String(tipText.contentEditable || '').toLowerCase();
    if (editable === 'true') return;

    const parsed = parseInt(rawValue, 10);
    if (Number.isFinite(parsed) && parsed > 0) {
        tipText.style.fontSize = `${parsed}px`;
        return;
    }

    tipText.style.removeProperty('font-size');
}

function __applyPermanentTipRealtimeSync(storageKey, rawValue) {
    const parsed = __parsePermanentTipStorageKey(storageKey);
    if (!parsed) return;
    if (!__shouldApplyPermanentTipRealtimeSync(storageKey)) return;

    const sectionEl = __findPermanentTipSectionByStorageKey(parsed);
    if (!sectionEl) return;

    if (parsed.type === 'font-size') {
        __applyPermanentTipFontSizeRealtimeSync(sectionEl, rawValue);
        return;
    }

    __applyPermanentTipContentRealtimeSync(sectionEl, rawValue);
}

function __applyDescHeightSettingsRealtimeSync(storageKey, rawValue) {
    const isTempDesc = storageKey === TEMP_DESC_HEIGHT_SETTINGS_KEY;
    const isPermanentDesc = storageKey === PERMANENT_DESC_HEIGHT_SETTINGS_KEY;
    if (!isTempDesc && !isPermanentDesc) return;

    const parsed = __safeParseCanvasStorageJson(rawValue);
    const defaults = {
        displayMode: 'rows',
        displayRows: 4,
        editMode: 'full',
        editRows: 5
    };
    const normalized = __readDescHeightSettings(
        storageKey,
        defaults,
        (parsed && typeof parsed === 'object') ? parsed : null
    );

    const selector = isTempDesc ? '.temp-node-description-container' : '.permanent-section-tip-container';
    document.querySelectorAll(selector).forEach((el) => {
        if (!el) return;
        try {
            el.__descHeightSettings = {
                displayMode: normalized.displayMode,
                displayRows: normalized.displayRows,
                editMode: normalized.editMode,
                editRows: normalized.editRows
            };
            if (typeof el.__applyDescHeightSettings === 'function') {
                el.__applyDescHeightSettings();
            }
        } catch (_) { }
    });
}

function __handleCanvasRealtimeLocalStorageSync(key, rawValue) {
    if (key === BCS_SIGNAL_KEY) {
        const state = __safeParseCanvasStorageJson(rawValue);
        if (state) {
            __consumeCanvasTempStateRealtimeSignal(state, 'localStorage');
        }
        return;
    }

    if (key === CANVAS_VIEW_SYNC_SIGNAL_KEY) {
        const payload = __safeParseCanvasStorageJson(rawValue);
        if (payload) {
            __consumeCanvasViewSyncSignal(payload, 'localStorage');
        }
        return;
    }

    if (key === CANVAS_APPEARANCE_SETTINGS_KEY) {
        __applyCanvasAppearanceRealtimeSync(rawValue);
        return;
    }

    if (key === CANVAS_OTHER_SETTINGS_KEY) {
        __applyCanvasOtherSettingsRealtimeSync(rawValue);
        return;
    }

    if (key === PERMANENT_SECTION_COPIES_STORAGE_KEY) {
        __applyPermanentSectionCopiesRealtimeSync(rawValue);
        return;
    }

    if (key === TEMP_DESC_HEIGHT_SETTINGS_KEY || key === PERMANENT_DESC_HEIGHT_SETTINGS_KEY) {
        __applyDescHeightSettingsRealtimeSync(key, rawValue);
        return;
    }

    if (typeof key === 'string' && key.startsWith(PERMANENT_TIP_TIMESTAMP_KEY_PREFIX)) {
        return;
    }

    // 永久栏目说明（含副本）不在 CanvasState 主快照中，
    // 因此需要按 key 前缀走 localStorage 实时回灌。
    if (
        key === PERMANENT_MAIN_TIP_STORAGE_KEY
        || key === `${PERMANENT_MAIN_TIP_STORAGE_KEY}-font-size`
        || (typeof key === 'string' && key.startsWith(PERMANENT_COPY_TIP_STORAGE_PREFIX))
    ) {
        __applyPermanentTipRealtimeSync(key, rawValue);
        return;
    }

    if (
        key === 'canvasDataIntensiveThresholds'
        || key === 'canvasDataIntensiveEnabled'
        || key === 'canvasDataIntensiveTotalAlwaysEnabled'
        || key === 'canvasDataIntensiveTotalAlwaysThresholds'
        || key === 'canvasLowDetailEnabled'
        || key === 'canvasZoomThresholds'
        || key === 'canvasSafeZoneSettings'
        || key === 'canvasMinZoomLimit'
        || key === 'canvasZoomMagnetSettings'
    ) {
        try { loadCanvasDataIntensiveSettings(); } catch (_) { }
        try { updateDataIntensiveMode(true); } catch (_) { }
    }
}

function __debugCanvasSyncState() {
    const partitionKey = __getCanvasViewPartitionKey();
    const camera = __getCanvasCameraStorageKeys();

    const sharedKeys = [
        BCS_SIGNAL_KEY,
        CANVAS_APPEARANCE_SETTINGS_KEY,
        CANVAS_OTHER_SETTINGS_KEY,
        PERMANENT_SECTION_COPIES_STORAGE_KEY
    ];

    const partitionKeys = [
        __buildCanvasPartitionedViewStateKey('expand', TEMP_EXPAND_STATE_KEY),
        __buildCanvasPartitionedViewStateKey('expand', PERMANENT_SECTION_EXPANDED_KEY),
        __buildCanvasPartitionedViewStateKey('scroll', PERMANENT_SECTION_SCROLL_KEY),
        camera && camera.zoomKey,
        camera && camera.panKey
    ].filter(Boolean);

    const exists = {};
    const read = (key) => {
        if (!key) return null;
        try {
            const value = localStorage.getItem(key);
            exists[key] = value !== null;
            return value;
        } catch (_) {
            exists[key] = false;
            return null;
        }
    };

    const shared = {};
    sharedKeys.forEach((key) => {
        const value = read(key);
        shared[key] = value;
    });

    let permanentTipCount = 0;
    let partitionedViewKeyCount = 0;
    let tempRootVisibleKeyCount = 0;
    let legacyTempRootVisibleKeyCount = 0;
    try {
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (!key) continue;
            if (
                key === PERMANENT_MAIN_TIP_STORAGE_KEY
                || key === `${PERMANENT_MAIN_TIP_STORAGE_KEY}-font-size`
                || key.startsWith(PERMANENT_COPY_TIP_STORAGE_PREFIX)
            ) permanentTipCount += 1;
            if (key.startsWith(`${CANVAS_VIEW_STATE_STORAGE_NS}:`)) partitionedViewKeyCount += 1;
            if (key.startsWith(`${CANVAS_VIEW_STATE_STORAGE_NS}:view:${partitionKey}:${TEMP_ROOT_VISIBLE_KEY_PREFIX}`)) {
                tempRootVisibleKeyCount += 1;
            }
            if (key.startsWith(TEMP_ROOT_VISIBLE_KEY_PREFIX)) legacyTempRootVisibleKeyCount += 1;
        }
    } catch (_) { }

    const partition = {};
    partitionKeys.forEach((key) => {
        partition[key] = read(key);
    });

    const result = {
        partitionKey,
        surfaceKey: __getCanvasViewSurfaceKey(),
        schema: {
            current: __readCanvasStorageSchemaVersion(),
            target: CANVAS_STORAGE_SCHEMA_VERSION
        },
        counts: {
            permanentTipKeyCount: permanentTipCount,
            partitionedViewKeyCount,
            tempRootVisibleKeyCount,
            legacyTempRootVisibleKeyCount
        },
        shared,
        partition,
        exists
    };

    try {
        console.groupCollapsed(`[CanvasSyncDebug] partition=${partitionKey}`);
        console.log(result);
        console.groupEnd();
    } catch (_) {
        console.log(result);
    }

    return result;
}
window.__debugCanvasSyncState = __debugCanvasSyncState;

function __bindCanvasTempStateRealtimeSync() {
    if (__canvasTempStateRealtimeSyncBound) return;
    __canvasTempStateRealtimeSyncBound = true;

    // localStorage 通道：覆盖当前页使用 localStorage 持久化的场景。
    try {
        if (typeof window !== 'undefined' && window && typeof window.addEventListener === 'function') {
            window.addEventListener('storage', (event) => {
                if (!event || !event.key) return;
                __handleCanvasRealtimeLocalStorageSync(event.key, event.newValue);
            });
        }
    } catch (_) { }

    // chrome.storage 通道：覆盖扩展跨文档（标签页/窗口/侧边栏）同步主路径。
    const onChanged = __getCanvasStorageOnChangedArea();
    if (onChanged && typeof onChanged.addListener === 'function') {
        try {
            onChanged.addListener((changes, areaName) => {
                if (areaName !== 'local' || !changes) return;
                const entry = changes[BCS_SIGNAL_KEY];
                if (!entry || !Object.prototype.hasOwnProperty.call(entry, 'newValue')) return;
                __consumeCanvasTempStateRealtimeSignal(entry.newValue, 'storage.onChanged');
            });
        } catch (_) { }
    }
}

function __applyCanvasTempStateObject(state, options = {}) {
    const preserveRaw = !!(options && options.preserveRaw === true);
    const sourceState = __normalizeCanvasTempStateForRuntime(state, {
        preserveRaw
    }) || ((state && typeof state === 'object') ? state : {});

    CanvasState.tempSections = Array.isArray(sourceState.sections)
        ? sourceState.sections
        : (Array.isArray(sourceState.tempSections) ? sourceState.tempSections : []);
    CanvasState.tempSectionCounter = sourceState.tempSectionCounter || CanvasState.tempSections.length;
    CanvasState.tempItemCounter = sourceState.tempItemCounter || 0;
    CanvasState.colorCursor = sourceState.colorCursor || 0;
    CanvasState.tempSectionLastColor = sourceState.tempSectionLastColor || getTempSectionDefaultColor();
    CanvasState.tempSectionPrevColor = sourceState.tempSectionPrevColor || null;
    CanvasState.mdNodes = Array.isArray(sourceState.mdNodes)
        ? sourceState.mdNodes
        : (Array.isArray(sourceState.cards) ? sourceState.cards : []);
    CanvasState.mdNodeCounter = sourceState.mdNodeCounter || CanvasState.mdNodes.length || 0;
    CanvasState.edges = Array.isArray(sourceState.edges) ? sourceState.edges : [];
    CanvasState.edgeCounter = sourceState.edgeCounter || CanvasState.edges.length || 0;

    // One-shot id migration: any section whose id is from the abandoned tempSecId_* scheme
    // (commit 2298735) or the legacy temp-section-<N> numeric scheme gets renamed to the
    // canonical temp-section-<label-chain> form. Uses rewriteTempSectionId so item.sectionId,
    // edges and containedTempIds stay consistent.
    try {
        const needsRewrite = [];
        for (const section of CanvasState.tempSections) {
            if (!section || typeof section.id !== 'string') continue;
            const id = section.id;
            // doc 第三轮修复 §2.5: 防御性兜底——加 `temp-section-pending-*` 前缀。
            // 现行 createTempNode 已不再产出这种中间态字符串，但保留识别能力以清理
            // 历史数据里残留的 pending id（例如旧版本写入的 state）。
            const isLegacy = /^temp-section-\d+$/.test(id)
                || /^tempSecId_/.test(id)
                || /^temp-section-protocol-/.test(id)
                || /^temp-section-pending-/.test(id);
            if (!isLegacy) continue;
            const correctedId = buildTempSectionIdFromSection(section);
            if (correctedId && correctedId !== id) needsRewrite.push([id, correctedId]);
        }
        let migratedAny = false;
        for (const [oldId, newId] of needsRewrite) {
            if (rewriteTempSectionId(oldId, newId)) migratedAny = true;
        }
        // doc 最终修复计划 §3.6 step 4: 迁移后立即保存，避免刷新后重复迁移与潜在重复 id。
        if (migratedAny) {
            try { if (typeof saveTempNodes === 'function') saveTempNodes(); } catch (_) {}
        }
    } catch (e) { console.warn('[Canvas] section-id migration on load failed:', e); }

    const ts = __extractCanvasTempStateTimestamp(sourceState);
    if (ts > 0) {
        __canvasTempStateLastAppliedTimestamp = Math.max(__canvasTempStateLastAppliedTimestamp, ts);
    }
    const loadedSignature = __buildCanvasTempStateSignature(sourceState);
    if (loadedSignature) {
        __canvasTempStateLastPersistedSignature = loadedSignature;
    }
    // 区块休眠替代旧休眠：加载时不保留运行态 dormant 标记，避免“空白/隐藏栏目”
    try {
        (CanvasState.tempSections || []).forEach((s) => {
            if (!s || typeof s !== 'object') return;
            if ('dormant' in s) {
                try { delete s.dormant; } catch (_) { s.dormant = false; }
            }
        });
    } catch (_) { }

    try {
        (CanvasState.mdNodes || []).forEach((node) => {
            const refreshCachesFromMarkdown = __isCanvasNativeTextNode(node)
                ? !(typeof node.html === 'string' && node.html.trim())
                : true;
            __ensureMdNodeMarkdownProtocol(node, {
                refreshCachesFromMarkdown
            });
        });
    } catch (_) { }
}

function __finalizeTempNodesLoad({ loadedFromStorage }) {
    // 根据已有ID刷新计数
    refreshTempSectionCounters();
    __refreshCanvasNodeCounters();

    // 恢复序号计数器（找到最大的序号）
    let maxSequenceNumber = 0;
    CanvasState.tempSections.forEach(section => {
        if (section.sequenceNumber && section.sequenceNumber > maxSequenceNumber) {
            maxSequenceNumber = section.sequenceNumber;
        }
    });
    CanvasState.tempSectionSequenceNumber = maxSequenceNumber;

    // 序号系统升级：把旧版的 A1 / A1-1 ... 统一转换为 A-1-1 / A-1-1-1 ...（不影响用户自定义的新格式）
    try { __normalizeExistingTempSectionLabels(); } catch (_) { }

    let shouldRenderShellOnly = false;
    suppressScrollSync = true;
    try {
        shouldRenderShellOnly = isCanvasVirtualizationEnabled() || isCanvasBlockDormancyEnabled();
        const mdBaseSize = getBlankNodeDefaultSize();
        CanvasState.tempSections.forEach(section => {
            const baseSize = getTempSectionBaseSize(section);
            section.width = section.width || baseSize.width;
            section.height = section.height || baseSize.height;
            // 大数据/极限模式 / 区块休眠：先渲染“壳体”，树内容按需加载（避免启动即卡死/一上来全量加载）
            renderTempNode(section, shouldRenderShellOnly ? { skipTree: true } : {});
        });
        // 渲染 Markdown 文本卡片
        CanvasState.mdNodes.forEach(node => {
            node.width = node.width || mdBaseSize.width;
            node.height = node.height || mdBaseSize.height;
            renderMdNode(node);
        });
    } finally {
        suppressScrollSync = false;
    }

    if (!shouldRenderShellOnly) {
        try { applyTempSectionAutoSizeAll(); } catch (_) { }
    }

    console.log(`[Canvas] 加载了 ${CanvasState.tempSections.length} 个临时栏目`);

    loadPermanentSectionPosition();
    updateCanvasScrollBounds();
    updateScrollbarThumbs();

    // 初始化按需加载 / 休眠状态
    if (isCanvasVirtualizationEnabled()) {
        scheduleCanvasVirtualizationUpdate(60);
    } else {
        // 区块休眠/普通休眠：尽快执行一次按需加载（启动阶段不必等待 200ms 的默认节流）
        scheduleDormancyUpdate(60);
    }

    // 渲染连接线（大数据/极限模式下延后，避免启动重建所有边）
    if (!isCanvasVirtualizationEnabled()) {
        renderEdges();
    } else {
        try { scheduleEdgesRender(); } catch (_) { }
    }

    // 初始预置卡片兼容：
    // - 只要当前状态仍是“初始三张演示卡”的原始模板，并且当前视图分区还没有保存过镜头，
    //   就强制把镜头定位到三卡中心，避免 sidepanel 首次打开时看起来像“卡片消失”。
    // - 首次 fallback 到演示模板时，立即把模板持久化到 BCS，避免升级/重载后再次落回空状态。
    const openedKey = 'bookmark-canvas-has-opened';
    const hasOpenedCanvas = localStorage.getItem(openedKey) === 'true';
    const isPristineDemoPreset = __isPristineDemoPresetCanvasState(CanvasState);
    const hasSavedPartitionPan = __hasSavedCameraPanForCurrentPartition();
    const shouldLocateIntroCards = isPristineDemoPreset && (!hasSavedPartitionPan || (!hasOpenedCanvas && !loadedFromStorage));

    if (shouldLocateIntroCards) {
        try { locateToIntroCardsCenter(); } catch (_) { }
    } else if (!hasOpenedCanvas && !loadedFromStorage) {
        try { locateToIntroCardsCenter(); } catch (_) { }
    }

    if (isPristineDemoPreset && !loadedFromStorage) {
        try { saveTempNodes({ immediate: true }); } catch (_) { }
    }

    if (!hasOpenedCanvas) {
        try { saveSharedState(openedKey, 'true', { asJSON: false }); } catch (_) { }
    }

    // Restore maximized node state after all nodes are rendered
    __tryRestoreMaximizedNode({ clearIfMissing: false });

    // 通知首屏预置：Canvas 初始布局（含滚动条位置）已经就绪
    try {
        requestAnimationFrame(() => {
            try { updateCanvasScrollBounds({ initial: false, recomputeBounds: false }); } catch (_) { }
            try { updateScrollbarThumbs(); } catch (_) { }
            requestAnimationFrame(() => {
                try { updateCanvasScrollBounds({ initial: false, recomputeBounds: false }); } catch (_) { }
                try { updateScrollbarThumbs(); } catch (_) { }
                try { window.dispatchEvent(new CustomEvent('canvas-initial-layout-ready')); } catch (_) { }
            });
        });
    } catch (_) { }
}

function saveTempNodes(options = {}) {
    // [开发约定 - 新功能同步指南]
    // 1) 先改 CanvasState（tempSections / mdNodes / edges 等）
    // 2) 立即或节流后调用 saveTempNodes()
    // 3) 本函数负责：持久化 + 触发跨页面同步信号
    // 4) 若功能是“仅当前会话临时态”（如 sandbox 导入），不要调用本函数
    if (__canvasTempStateRealtimeSyncApplying) return;
    const immediate = !!(options && options.immediate);
    const skipUnchangedPersist = !!(options && options.skipUnchangedPersist);
    // 保存前执行自动 resize
    autoResizeImportContainers();

    try {
        (CanvasState.mdNodes || []).forEach((node) => {
            const refreshCachesFromMarkdown = __isCanvasNativeTextNode(node)
                ? false
                : true;
            __ensureMdNodeMarkdownProtocol(node, {
                refreshCachesFromMarkdown
            });
        });
    } catch (_) { }

    try {
        const state = {
            sections: CanvasState.tempSections,
            tempSectionCounter: CanvasState.tempSectionCounter,
            tempItemCounter: CanvasState.tempItemCounter,
            colorCursor: CanvasState.colorCursor,
            tempSectionLastColor: CanvasState.tempSectionLastColor || getTempSectionDefaultColor(),
            tempSectionPrevColor: CanvasState.tempSectionPrevColor || null,
            // 新增：保存 Markdown 文本卡片
            mdNodes: CanvasState.mdNodes,
            mdNodeCounter: CanvasState.mdNodeCounter,
            // 新增：保存连接线
            edges: CanvasState.edges,
            edgeCounter: CanvasState.edgeCounter,
            timestamp: Date.now()
        };
        const persistedState = __buildPersistedCanvasState(state);
        const persistedSignature = __buildCanvasTempStateSignature(persistedState);
        if (
            skipUnchangedPersist
            && persistedSignature
            && __canvasTempStateLastPersistedSignature
            && persistedSignature === __canvasTempStateLastPersistedSignature
        ) {
            return;
        }
        if (persistedSignature) {
            __canvasTempStateLastPersistedSignature = persistedSignature;
        }
        const persistedTs = __extractCanvasTempStateTimestamp(persistedState);
        if (persistedTs > 0) {
            __canvasTempStateLastSavedTimestamp = Math.max(__canvasTempStateLastSavedTimestamp, persistedTs);
            __canvasTempStateLastAppliedTimestamp = Math.max(__canvasTempStateLastAppliedTimestamp, persistedTs);
        }
        return __saveCanvasTempStateToBcsStorage(persistedState, {
            immediate
        });

    } catch (error) {
        console.error('[Canvas] 保存临时栏目失败:', error);
    }
}

function loadTempNodes() {
    try {
        CanvasState.tempSections = [];
        CanvasState.tempSectionCounter = 0;
        CanvasState.tempItemCounter = 0;
        CanvasState.colorCursor = 0;
        CanvasState.tempSectionLastColor = getTempSectionDefaultColor();
        CanvasState.tempSectionPrevColor = null;
        CanvasState.mdNodes = [];
        CanvasState.mdNodeCounter = 0;
        CanvasState.edges = [];
        CanvasState.edgeCounter = 0;

        // 仅使用 BCS 分片恢复（按严格分片存储方案执行）。
        if (__tryRestoreTempNodesFromBcs()) {
            return;
        }

        // 首次使用：加载初始演示模板
        CanvasState.tempSections = [];
        const demoTemplate = createInitialDemoTemplate();
        CanvasState.mdNodes = demoTemplate.mdNodes;
        CanvasState.mdNodeCounter = demoTemplate.mdNodeCounter;
        CanvasState.edges = demoTemplate.edges;
        CanvasState.edgeCounter = demoTemplate.edgeCounter;
        console.log('[Canvas] 首次使用，加载演示模板');

        __finalizeTempNodesLoad({ loadedFromStorage: false });
    } catch (error) {
        console.error('[Canvas] 加载临时栏目失败:', error);
    }
}

// =============================================================================
// 连接线功能 (Obsidian Canvas 风格)
// =============================================================================

function setupCanvasEdgesLayer() {
    const content = document.getElementById('canvasContent');
    if (!content) return;
    if (content.querySelector('.canvas-edges')) return;

    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('class', 'canvas-edges');
    // 设置样式：Z-Index 介于 Container(5) 和 TempSections(10) 之间
    svg.style.position = 'absolute';
    svg.style.top = '0';
    svg.style.left = '0';
    svg.style.width = '100%';
    svg.style.height = '100%';
    svg.style.zIndex = '7';
    svg.style.pointerEvents = 'none'; // Pass through clicks to container unless hitting a path
    // Insert as first child so it's behind everything
    content.insertBefore(svg, content.firstChild);

    // Create arrowhead marker once for edge directions
    try {
        if (!svg.querySelector('#edge-arrowhead')) {
            const defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs');
            const marker = document.createElementNS('http://www.w3.org/2000/svg', 'marker');
            marker.setAttribute('id', 'edge-arrowhead');
            // Smaller, subtler arrowhead
            marker.setAttribute('markerWidth', '8');
            marker.setAttribute('markerHeight', '8');
            marker.setAttribute('refX', '7');
            marker.setAttribute('refY', '4');
            marker.setAttribute('orient', 'auto-start-reverse');
            marker.setAttribute('markerUnits', 'strokeWidth');
            const p = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            p.setAttribute('d', 'M0,0 L8,4 L0,8 z');
            p.setAttribute('fill', 'context-stroke');
            p.setAttribute('stroke', 'none');
            marker.appendChild(p);
            defs.appendChild(marker);
            svg.appendChild(defs);
        }
    } catch (_) { }
}

function addAnchorsToNode(nodeElement, nodeId) {
    if (!nodeElement) return;
    // Don't add anchors to the permanent section
    // [Fix] 恢复永久栏目的连接点（用户反馈需要）
    // if (nodeId === 'permanent-section' || nodeElement.id === 'permanentSection') return;
    // Remove existing anchors and zones if any to avoid duplicates
    nodeElement.querySelectorAll('.canvas-node-anchor, .canvas-anchor-zone').forEach(el => el.remove());

    ['top', 'right', 'bottom', 'left'].forEach(side => {
        // Create hover zone first (so it can affect anchor via sibling selector if needed, 
        // though we might use JS for more reliable hover handling if CSS is tricky)
        const zone = document.createElement('div');
        zone.className = `canvas-anchor-zone zone-${side}`;
        zone.dataset.side = side;
        nodeElement.appendChild(zone);

        const anchor = document.createElement('div');
        anchor.className = 'canvas-node-anchor';
        anchor.dataset.nodeId = nodeId;
        anchor.dataset.side = side;
        nodeElement.appendChild(anchor);

        anchor.addEventListener('mousedown', (e) => {
            startConnection(e, nodeId, side);
        }, true);
    });

    // =============================================================================
    // 【重要架构】临时栏目书签左键点击处理器
    // =============================================================================
    // 本处理器是「书签系统」的一部分，与永久栏目的处理逻辑（history.js:attachTreeEvents）
    // 必须保持同步！两者都使用 window.defaultOpenMode 变量。
    //
    // ⚠️ 添加新的打开模式时，必须同时修改：
    //   1. history.js → attachTreeEvents → clickHandler（永久栏目）
    //   2. 本文件 → tempLinkClickHandler（临时栏目）
    //   3. bookmark_tree_context_menu.js → 右键菜单action处理
    //
    // 详见：.agent/workflows/link-click-handling.md
    // =============================================================================
    // 左键点击临时栏目（书签型）中的书签链接时，按全局默认打开方式处理
    if (tempLinkClickHandler) {
        document.removeEventListener('click', tempLinkClickHandler, true);
        document.removeEventListener('click', tempLinkClickHandler, false);
    }
    tempLinkClickHandler = (e) => {
        const link = e.target && e.target.closest('.temp-canvas-node a.tree-bookmark-link');
        if (!link) return;
        // Select（批量）模式下：点击应当用于“选择”，不应触发默认打开逻辑
        // 注意：selectMode 变量定义在 bookmark_tree_context_menu.js（全局作用域共享）
        try {
            if (typeof selectMode !== 'undefined' && selectMode) return;
        } catch (_) { }
        // 修饰键交给浏览器默认行为
        if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
        e.preventDefault();
        // 阻止其它监听器重复处理
        if (typeof e.stopImmediatePropagation === 'function') e.stopImmediatePropagation();
        if (typeof e.stopPropagation === 'function') e.stopPropagation();
        const url = link.getAttribute('href');
        // 解析作用域上下文（临时栏目）
        const tempNode = link.closest('.temp-canvas-node[data-section-id]');
        const scopedContext = tempNode ? { treeType: 'temporary', sectionId: tempNode.dataset.sectionId } : { treeType: 'permanent' };
        try {
            if (window.defaultOpenMode === undefined && typeof window.getDefaultOpenMode === 'function') {
                window.defaultOpenMode = window.getDefaultOpenMode();
            }
        } catch (_) { }
        const mode = (typeof window !== 'undefined' && window.defaultOpenMode) || 'new-tab';
        if (mode === 'new-window') {
            if (typeof window.openBookmarkNewWindow === 'function') window.openBookmarkNewWindow(url, false); else window.open(url, '_blank');
        } else if (mode === 'incognito') {
            if (typeof window.openBookmarkNewWindow === 'function') window.openBookmarkNewWindow(url, true); else window.open(url, '_blank');
        } else if (mode === 'specific-window') {
            if (typeof window.openInSpecificWindow === 'function') window.openInSpecificWindow(url); else window.open(url, '_blank');
        } else if (mode === 'scoped-window') {
            if (typeof window.openInScopedWindow === 'function') window.openInScopedWindow(url, { context: scopedContext }); else window.open(url, '_blank');
        } else if (mode === 'specific-group') {
            if (typeof window.openInSpecificTabGroup === 'function') window.openInSpecificTabGroup(url); else window.open(url, '_blank');
        } else if (mode === 'scoped-group') {
            if (typeof window.openInScopedTabGroup === 'function') window.openInScopedTabGroup(url, { context: scopedContext }); else window.open(url, '_blank');
        } else if (mode === 'same-window-specific-group') {
            if (typeof window.openInSameWindowSpecificGroup === 'function') window.openInSameWindowSpecificGroup(url, { context: scopedContext }); else window.open(url, '_blank');
        } else if (mode === 'manual-select') {
            if (typeof window.openBookmarkWithManualSelection === 'function') window.openBookmarkWithManualSelection(url); else window.open(url, '_blank');
        } else {
            if (typeof window.openBookmarkNewTab === 'function') window.openBookmarkNewTab(url); else window.open(url, '_blank');
        }
    };
    document.addEventListener('click', tempLinkClickHandler, true);
}

function startConnection(e, nodeId, side) {
    e.stopPropagation();
    e.preventDefault();
    CanvasState.isConnecting = true;
    CanvasState.connectionStart = { nodeId, side, x: e.clientX, y: e.clientY };
    const workspace = document.getElementById('canvasWorkspace');
    if (workspace) workspace.classList.add('connecting');

    // 隐藏连接线工具栏
    hideEdgeToolbar();

    // Create temporary path for dragging
    const svg = document.querySelector('.canvas-edges');
    if (svg) {
        let tempPath = document.getElementById('temp-connection-path');
        if (!tempPath) {
            tempPath = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            tempPath.setAttribute('id', 'temp-connection-path');
            tempPath.setAttribute('class', 'canvas-edge');
            tempPath.style.opacity = '0.5';
            svg.appendChild(tempPath);
        }
    }
}

function updateConnection(e) {
    if (!CanvasState.isConnecting || !CanvasState.connectionStart) return;
    e.preventDefault();

    const svg = document.querySelector('.canvas-edges');
    const tempPath = document.getElementById('temp-connection-path');
    if (!svg || !tempPath) return;

    const startPos = getAnchorPosition(CanvasState.connectionStart.nodeId, CanvasState.connectionStart.side);
    if (!startPos) return;

    // Calculate end position in canvas coordinates
    const rect = svg.getBoundingClientRect();
    const zoom = CanvasState.zoom || 1;
    const endX = (e.clientX - rect.left) / zoom;
    const endY = (e.clientY - rect.top) / zoom;

    const d = getEdgePathD(startPos.x, startPos.y, endX, endY, CanvasState.connectionStart.side, null);
    tempPath.setAttribute('d', d);
}

function endConnection(e) {
    if (!CanvasState.isConnecting) return;
    CanvasState.isConnecting = false;
    const workspace = document.getElementById('canvasWorkspace');
    if (workspace) workspace.classList.remove('connecting');

    const tempPath = document.getElementById('temp-connection-path');
    if (tempPath) tempPath.remove();

    // Use composedPath if available to get all elements under cursor, 
    // or just elementFromPoint. elementFromPoint might hit the dragging line if not careful,
    // but we removed it just above.
    const target = document.elementFromPoint(e.clientX, e.clientY);
    const anchor = target ? target.closest('.canvas-node-anchor') : null;
    const nodeEl = target ? target.closest('.temp-canvas-node, .md-canvas-node, .permanent-bookmark-section') : null;

    if (CanvasState.connectionStart) {
        let toNodeId = null;
        let toSide = null;

        if (anchor) {
            toNodeId = anchor.dataset.nodeId;
            toSide = anchor.dataset.side;
        } else if (nodeEl) {
            // Dropped on a node but not an anchor -> auto-connect to nearest side
            toNodeId = nodeEl.id;
            // Special case for permanent section ID normalization
            if (toNodeId === 'permanentSection') toNodeId = 'permanent-section';

            const rect = nodeEl.getBoundingClientRect();
            toSide = getNearestSide(rect, e.clientX, e.clientY);
        }

        if (toNodeId && toSide) {
            const fromNodeId = CanvasState.connectionStart.nodeId;
            const fromSide = CanvasState.connectionStart.side;
            // Block same-node connections entirely
            if (toNodeId === fromNodeId) {
                console.log('[Canvas] 忽略同栏目的锚点连接');
            } else if (toNodeId !== fromNodeId || toSide !== fromSide) {
                addEdge(fromNodeId, fromSide, toNodeId, toSide);

                // Delay toolbar appearance for md-canvas-node after connection
                if (nodeEl && nodeEl.classList.contains('md-canvas-node')) {
                    nodeEl.classList.add('connection-just-finished');
                    setTimeout(() => {
                        nodeEl.classList.remove('connection-just-finished');
                    }, 1000);
                }
            }
        }
    }
    CanvasState.connectionStart = null;
}

function getNearestSide(rect, x, y) {
    const distTop = Math.abs(y - rect.top);
    const distBottom = Math.abs(y - rect.bottom);
    const distLeft = Math.abs(x - rect.left);
    const distRight = Math.abs(x - rect.right);
    const min = Math.min(distTop, distBottom, distLeft, distRight);
    if (min === distTop) return 'top';
    if (min === distBottom) return 'bottom';
    if (min === distLeft) return 'left';
    return 'right';
}

function addEdge(fromNode, fromSide, toNode, toSide) {
    // Check for existing identical edge
    const exists = CanvasState.edges.some(e =>
        e.fromNode === fromNode && e.fromSide === fromSide &&
        e.toNode === toNode && e.toSide === toSide
    );
    if (exists) return;
    // Block self-connections between anchors of the same node
    if (fromNode === toNode) {
        console.log('[Canvas] 忽略同栏目的锚点连接');
        return;
    }

    const defaultLabel = getDefaultEdgeLabel({ fromNode, toNode });
    const defaultColor = getEdgeDefaultColor();
    const id = `edge - ${++CanvasState.edgeCounter} -${Date.now()} `;
    CanvasState.edges.push({
        id,
        fromNode,
        fromSide,
        toNode,
        toSide,
        direction: 'none', // 'none' | 'forward' | 'both'
        color: null, // 预设颜色编号 (1-6) 或 null
        colorHex: defaultColor || null, // 自定义十六进制颜色
        label: defaultLabel || '' // 连接线文字标签
    });
    renderEdges();
    saveTempNodes();
}

// Remove all edges attached to a given node (section/md/permanent)
function removeEdgesForNode(nodeId, options = {}) {
    const skipSave = !!(options && options.skipSave);
    const immediate = options && Object.prototype.hasOwnProperty.call(options, 'immediate')
        ? !!options.immediate
        : true;
    const before = CanvasState.edges.length;
    const removed = [];
    CanvasState.edges = CanvasState.edges.filter(e => {
        const match = (e.fromNode === nodeId) || (e.toNode === nodeId);
        if (match) removed.push(e.id);
        return !match;
    });
    if (removed.includes(CanvasState.selectedEdgeId)) {
        CanvasState.selectedEdgeId = null;
        hideEdgeToolbar();
    }
    if (removed.length) {
        renderEdges();
        if (!skipSave) {
            saveTempNodes({ immediate });
        }
        console.log(`[Canvas] 已移除与节点 ${nodeId} 相连的连接线: ${removed.length}/${before}`);
    }
}

function removeEdge(edgeId) {
    CanvasState.edges = CanvasState.edges.filter(e => e.id !== edgeId);
    if (CanvasState.selectedEdgeId === edgeId) {
        clearEdgeSelection();
    }
    renderEdges();
    saveTempNodes();
}

let edgesRenderTimer = null;
let edgesRenderPending = false;
let edgesRenderRetryTimer = null;

function shouldSkipEdgesRender() {
    // [Fix] 虚拟化开启时不应该隐藏连接线，否则永远看不见线了（因为虚拟化现已强制开启）
    // if (isCanvasVirtualizationEnabled()) return true;
    // 边太多时也直接跳过（避免频繁 rebuild DOM/SVG）
    const edgeCount = Array.isArray(CanvasState.edges) ? CanvasState.edges.length : 0;
    if (edgeCount > 240 && isCanvasHugeData()) return true;
    return false;
}

function scheduleEdgesRender(delayMs = 90) {
    if (edgesRenderPending) return;
    edgesRenderPending = true;
    if (edgesRenderTimer) clearTimeout(edgesRenderTimer);
    edgesRenderTimer = setTimeout(() => {
        edgesRenderTimer = null;
        edgesRenderPending = false;
        const ws = document.getElementById('canvasWorkspace');
        const isInteracting = ws && (isScrolling || CanvasState.isPanning || CanvasState.dragState.isDragging || ws.classList.contains('is-zooming'));
        if (isInteracting) {
            scheduleEdgesRender(isCanvasHugeData() ? 260 : 140);
            return;
        }
        try { renderEdges(); } catch (_) { }
    }, delayMs);
}

function scheduleEdgesRenderRetry(delayMs = 80) {
    if (edgesRenderRetryTimer) return;
    edgesRenderRetryTimer = setTimeout(() => {
        edgesRenderRetryTimer = null;
        try { scheduleEdgesRender(0); } catch (_) { }
    }, Math.max(0, delayMs));
}

let canvasPerfHudTimer = null;

function __isCanvasPerfHudEnabled() {
    try {
        const url = new URL(window.location.href);
        return url.searchParams.get('debugPerf') === '1';
    } catch (_) { }
    return false;
}

function __updateCanvasPerfHud() {
    if (!__isCanvasPerfHudEnabled()) return;
    const id = 'canvasPerfHud';
    let el = document.getElementById(id);
    if (!el) {
        el = document.createElement('div');
        el.id = id;
        el.style.cssText = [
            'position:fixed',
            'right:12px',
            'bottom:12px',
            'z-index:100001',
            'padding:8px 10px',
            'border-radius:10px',
            'font:12px/1.3 ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace',
            'background:rgba(0,0,0,0.72)',
            'color:#fff',
            'max-width:360px',
            'white-space:pre',
            'pointer-events:none'
        ].join(';');
        document.body.appendChild(el);
    }

    const tempCount = Array.isArray(CanvasState.tempSections) ? CanvasState.tempSections.length : 0;
    const mdCount = Array.isArray(CanvasState.mdNodes) ? CanvasState.mdNodes.length : 0;
    const edgeCount = Array.isArray(CanvasState.edges) ? CanvasState.edges.length : 0;
    const unloaded = CanvasState.unloadedTempSectionTrees && CanvasState.unloadedTempSectionTrees.size
        ? CanvasState.unloadedTempSectionTrees.size
        : 0;
    const displayZoom = getCanvasDisplayZoom();
    const virtual = isCanvasVirtualizationEnabled();
    const budget = virtual ? getCanvasVirtualizationBudget() : null;
    const loadedApprox = Math.max(0, tempCount - unloaded);

    // 数据密集模式信息
    const dim = CanvasState.dataIntensiveMode || {};
    const dimStats = dim.cachedStats || {};

    el.textContent =
        `Canvas Perf (debugPerf=1)\n` +
        `virtual=${virtual} lowDetail=${!!CanvasState.lowDetailActive}\n` +
        `displayZoom=${(displayZoom * 100).toFixed(1)}% rawZoom=${(CanvasState.zoom || 1).toFixed(3)}\n` +
        `temp=${tempCount} md=${mdCount} edges=${edgeCount}\n` +
        `treesLoaded≈${loadedApprox} unloaded=${unloaded}\n` +
        (budget ? `budget: maxLoaded=${budget.maxLoaded} marginPx=${budget.marginPx}\n` : '') +
        `dataIntensive=${!!dim.active} visSec=${dimStats.visibleSectionCount || 0} visBm=${dimStats.totalBookmarkCount || 0}`;
}

function setupCanvasPerfHud() {
    if (!__isCanvasPerfHudEnabled()) return;
    if (canvasPerfHudTimer) return;
    __updateCanvasPerfHud();
    canvasPerfHudTimer = setInterval(() => {
        try { __updateCanvasPerfHud(); } catch (_) { }
    }, 500);
}

function renderEdges() {
    const svg = document.querySelector('.canvas-edges');
    if (!svg) return;

    if (shouldSkipEdgesRender()) {
        svg.style.display = 'none';
        return;
    }
    svg.style.display = '';

    // Clear existing edges (except temp path if any)
    Array.from(svg.querySelectorAll('.canvas-edge, .canvas-edge-label, .canvas-edge-label-bg, .canvas-edge-hit-area, foreignObject.edge-label-fo')).forEach(el => {
        if (el.id !== 'temp-connection-path') el.remove();
    });

    // Stable z-order: render selected edge last to keep it on top
    const selectedId = CanvasState.selectedEdgeId || null;
    const edgesToRender = selectedId
        ? CanvasState.edges.filter(e => e.id !== selectedId).concat(CanvasState.edges.filter(e => e.id === selectedId))
        : CanvasState.edges.slice();

    let needsRetry = false;
    edgesToRender.forEach(edge => {
        const geometry = getEdgeRenderGeometry(edge);
        if (!geometry) {
            needsRetry = true;
            return;
        }

        // 创建不可见的宽点击区域（用于扩大点击识别范围）
        const hitArea = document.createElementNS('http://www.w3.org/2000/svg', 'path');
        hitArea.setAttribute('class', 'canvas-edge-hit-area');
        hitArea.dataset.edgeId = edge.id;
        hitArea.setAttribute('stroke', 'transparent');
        hitArea.setAttribute('stroke-width', '20'); // 更宽的点击区域
        hitArea.setAttribute('fill', 'none');
        hitArea.style.cursor = 'pointer';
        hitArea.style.pointerEvents = 'stroke';

        updateEdgePath(edge, hitArea, geometry);
        svg.appendChild(hitArea);

        // 创建可见的连接线路径
        const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
        path.setAttribute('class', 'canvas-edge');
        path.dataset.edgeId = edge.id;
        path.style.pointerEvents = 'none'; // 可见路径不响应点击，由 hitArea 处理
        if (edge.id === CanvasState.selectedEdgeId) {
            path.classList.add('selected');
        }

        // 应用颜色（使用 inline style 优先级高于样式表）
        const edgeColor = edge.colorHex || presetToHex(edge.color) || null;
        if (edgeColor) {
            path.style.stroke = edgeColor;
        } else {
            path.style.stroke = '';
        }
        // Apply arrow markers according to direction
        const dir = edge.direction || 'none';
        if (dir === 'forward') {
            path.setAttribute('marker-end', 'url(#edge-arrowhead)');
            path.removeAttribute('marker-start');
        } else if (dir === 'both') {
            path.setAttribute('marker-end', 'url(#edge-arrowhead)');
            path.setAttribute('marker-start', 'url(#edge-arrowhead)');
        } else {
            path.removeAttribute('marker-end');
            path.removeAttribute('marker-start');
        }
        // 选中时发光（使用与线条相同的颜色）
        if (edge.id === CanvasState.selectedEdgeId) {
            const glow = edgeColor || '#66bbff';
            path.style.filter = `drop-shadow(0 0 2px ${glow}66) drop-shadow(0 0 6px ${glow}99)`;
        } else {
            path.style.filter = '';
        }

        updateEdgePath(edge, path, geometry);
        svg.appendChild(path);

        // 点击事件绑定到不可见的宽区域
        hitArea.addEventListener('click', (e) => {
            console.log('[Edge] Edge clicked:', edge.id);
            e.stopPropagation();
            selectEdge(edge.id, e.clientX, e.clientY);
        });

        // 双击连接线直接进入编辑标签
        hitArea.addEventListener('dblclick', (e) => {
            console.log('[Edge] Edge double-clicked:', edge.id);
            e.stopPropagation();
            e.preventDefault();
            editEdgeLabel(edge.id);
        });

        // 悬停效果也应用到 hitArea
        hitArea.addEventListener('mouseenter', () => {
            path.classList.add('hover');
        });
        hitArea.addEventListener('mouseleave', () => {
            path.classList.remove('hover');
        });

        // 渲染标签（如果有）
        if (edge.label && edge.label.trim()) {
            renderEdgeLabel(svg, edge, geometry);
        }
    });

    if (needsRetry) {
        scheduleEdgesRenderRetry(isCanvasHugeData() ? 160 : 80);
    }

    // 更新工具栏位置（如果工具栏正在显示）
    updateEdgeToolbarPosition();
}

function renderEdgeLabel(svg, edge, geometry = null) {
    const resolved = geometry || getEdgeRenderGeometry(edge);
    if (!resolved) return;

    // 使用贝塞尔曲线中点放置标签，和曲线保持一致
    const midX = resolved.labelX;
    const midY = resolved.labelY;

    // 先创建背景挖空矩形（让连线在文字区域下方留出空白）
    // 注意：低细节模式下文字会“反向缩放”保持固定像素大小，若同时保留 rect 则尺寸会不匹配。
    // 因此仅在非低细节模式渲染背景矩形，退出低细节会通过 renderEdges() 重建。
    if (!CanvasState.lowDetailActive) {
        const textProbe = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        textProbe.setAttribute('class', 'canvas-edge-label');
        textProbe.setAttribute('x', midX);
        textProbe.setAttribute('y', midY);
        textProbe.setAttribute('text-anchor', 'middle');
        textProbe.setAttribute('dominant-baseline', 'middle');
        textProbe.textContent = edge.label;
        svg.appendChild(textProbe);

        // 计算文字尺寸
        let textWidth = 0;
        try { textWidth = textProbe.getComputedTextLength ? textProbe.getComputedTextLength() : 0; } catch (_) { }
        // 优先用BBox高度，回退到估算
        let textHeight = 16;
        try {
            const bb = textProbe.getBBox ? textProbe.getBBox() : null;
            if (bb && bb.height) textHeight = Math.ceil(bb.height);
        } catch (_) { }
        const padX = 6;
        const padY = 2;

        // 读取画布背景色，尽量与当前画布背景一致，形成“挖空”效果
        const getCanvasBg = () => {
            try {
                const ws = document.getElementById('canvasWorkspace');
                if (ws) {
                    const cs = getComputedStyle(ws);
                    const bg = cs && cs.backgroundColor ? cs.backgroundColor : null;
                    if (bg && bg !== 'rgba(0, 0, 0, 0)' && bg !== 'transparent') return bg;
                }
                const container = document.querySelector('.canvas-main-container');
                if (container) {
                    const cs = getComputedStyle(container);
                    const bg = cs && cs.backgroundColor ? cs.backgroundColor : null;
                    if (bg && bg !== 'rgba(0, 0, 0, 0)' && bg !== 'transparent') return bg;
                }
            } catch (_) { }
            return '#ffffff';
        };
        const bgColor = getCanvasBg();

        const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
        rect.setAttribute('x', (midX - textWidth / 2 - padX).toString());
        rect.setAttribute('y', (midY - textHeight / 2 - padY).toString());
        rect.setAttribute('width', (textWidth + padX * 2).toString());
        rect.setAttribute('height', (textHeight + padY * 2).toString());
        rect.setAttribute('rx', '4');
        rect.setAttribute('ry', '4');
        rect.setAttribute('fill', bgColor);
        rect.setAttribute('class', 'canvas-edge-label-bg');
        rect.setAttribute('data-edge-id', edge.id);
        rect.style.pointerEvents = 'none';

        // 计算完成后移除探针文本
        try { textProbe.remove(); } catch (_) { }
        // 将背景矩形插入到真实文本之前（盖住连线）
        svg.appendChild(rect);
    }

    // 创建标签文本元素（放在矩形之上）
    const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    text.setAttribute('class', 'canvas-edge-label');
    text.setAttribute('data-edge-id', edge.id);
    text.setAttribute('x', midX);
    text.setAttribute('y', midY);
    text.setAttribute('text-anchor', 'middle');
    text.setAttribute('dominant-baseline', 'middle');
    text.textContent = edge.label;

    // 应用颜色（inline style 覆盖样式表）
    const edgeColor = edge.colorHex || presetToHex(edge.color) || null;
    if (edgeColor) {
        text.style.fill = edgeColor;
    } else {
        text.style.fill = '';
    }

    svg.appendChild(text);

    // 标签点击事件：直接进入就地编辑
    text.addEventListener('click', (e) => {
        e.stopPropagation();
        try { selectEdge(edge.id, e.clientX, e.clientY); } catch (_) { }
        startEdgeLabelInlineEdit(edge.id);
    });
}

function getEdgeRenderGeometry(edge) {
    const start = getAnchorPosition(edge.fromNode, edge.fromSide);
    const end = getAnchorPosition(edge.toNode, edge.toSide);
    if (!start || !end) return null;

    const x1 = start.x, y1 = start.y;
    const x2 = end.x, y2 = end.y;
    const { cp1x, cp1y, cp2x, cp2y } = computeEdgeControlPoints(x1, y1, x2, y2, edge.fromSide, edge.toSide);
    const path = `M ${x1} ${y1} C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${x2} ${y2}`;
    const labelX = (x1 + 3 * cp1x + 3 * cp2x + x2) / 8;
    const labelY = (y1 + 3 * cp1y + 3 * cp2y + y2) / 8;

    return {
        path,
        labelX,
        labelY,
        sourceX: x1,
        sourceY: y1,
        targetX: x2,
        targetY: y2
    };
}

function updateEdgePath(edge, pathElement, geometry = null) {
    const resolved = geometry || getEdgeRenderGeometry(edge);

    if (resolved) {
        pathElement.setAttribute('d', resolved.path);
    } else {
        pathElement.setAttribute('d', '');
    }
}

function getAnchorPosition(nodeId, side) {
    let el = document.getElementById(nodeId);
    // Special case mapping for permanent section
    if (nodeId === 'permanent-section') el = document.getElementById('permanentSection');

    if (!el) return null;

    // Must use style.left/top because they are in canvas-content coordinates
    let left = parseFloat(el.style.left) || 0;
    let top = parseFloat(el.style.top) || 0;

    // 检查是否有 transform: translate() 应用（拖动过程中）
    const transform = el.style.transform;
    if (transform && transform.includes('translate')) {
        const match = transform.match(/translate\(([^,]+)px,\s*([^)]+)px\)/);
        if (match) {
            const translateX = parseFloat(match[1]) || 0;
            const translateY = parseFloat(match[2]) || 0;
            left += translateX;
            top += translateY;
        }
    }

    // [Drag] import-container 组拖动期间：节点位置由 CSS translate3d 驱动（不改 left/top）。
    // 连接线/工具栏计算位置时需手动补偿当前拖动位移，避免“松手瞬间漂移/跳变”。
    const dragMeta = CanvasState && CanvasState.dragState ? CanvasState.dragState.meta : null;
    if (dragMeta && dragMeta.importGroupDrag &&
        dragMeta.importGroupMovedIds && dragMeta.importGroupMovedIds.has &&
        dragMeta.importGroupMovedIds.has(nodeId)) {
        const dx = (typeof dragMeta.importGroupDx === 'number' && isFinite(dragMeta.importGroupDx)) ? dragMeta.importGroupDx : 0;
        const dy = (typeof dragMeta.importGroupDy === 'number' && isFinite(dragMeta.importGroupDy)) ? dragMeta.importGroupDy : 0;
        left += dx;
        top += dy;
    }

    const width = el.offsetWidth;
    const height = el.offsetHeight;

    switch (side) {
        case 'top': return { x: left + width / 2, y: top };
        case 'bottom': return { x: left + width / 2, y: top + height };
        case 'left': return { x: left, y: top + height / 2 };
        case 'right': return { x: left + width, y: top + height / 2 };
        default: return { x: left + width / 2, y: top + height / 2 };
    }
}

// Compute Bezier control points for an edge with aesthetics tuned for long distances
function computeEdgeControlPoints(x1, y1, x2, y2, side1, side2) {
    const ddx = x2 - x1;
    const ddy = y2 - y1;
    const adx = Math.abs(ddx);
    const ady = Math.abs(ddy);
    const dist = Math.hypot(ddx, ddy);

    const isHoriz = s => (s === 'left' || s === 'right');
    const isVert = s => (s === 'top' || s === 'bottom');
    const offsetAlongSide = (side, x, y, amt) => {
        switch (side) {
            case 'top': return { x, y: y - amt };
            case 'bottom': return { x, y: y + amt };
            case 'left': return { x: x - amt, y };
            case 'right': return { x: x + amt, y };
            default: return { x, y };
        }
    };

    // Near: compact "bracket" curve; Far: gentle curve with capped offset (avoid ugly large bows)
    const nearThreshold = 220;
    const nearAmt = Math.min(Math.max(dist * 0.45, 24), 80);
    const alongAmt = Math.min(Math.max(dist * 0.22, 40), 160);

    let cp1x = x1, cp1y = y1, cp2x = x2, cp2y = y2;

    if (dist < nearThreshold) {
        ({ x: cp1x, y: cp1y } = offsetAlongSide(side1, x1, y1, nearAmt));
        if (side2) ({ x: cp2x, y: cp2y } = offsetAlongSide(side2, x2, y2, nearAmt));
        const mx = (x1 + x2) / 2;
        const my = (y1 + y2) / 2;
        if (isHoriz(side1) && isHoriz(side2)) {
            cp1y = y1 + (my - y1) * 0.12;
            cp2y = y2 + (my - y2) * 0.12;
        } else if (isVert(side1) && isVert(side2)) {
            cp1x = x1 + (mx - x1) * 0.12;
            cp2x = x2 + (mx - x2) * 0.12;
        }
    } else {
        ({ x: cp1x, y: cp1y } = offsetAlongSide(side1, x1, y1, alongAmt));
        if (side2) ({ x: cp2x, y: cp2y } = offsetAlongSide(side2, x2, y2, alongAmt));
        // Very subtle perpendicular bend to avoid perfectly flat arcs and reduce crossings
        const bend = Math.min(12, alongAmt * 0.15);
        if (isHoriz(side1)) { cp1y += (ddy === 0 ? 1 : Math.sign(ddy)) * bend; }
        else { cp1x += (ddx === 0 ? 1 : Math.sign(ddx)) * bend; }
        if (isHoriz(side2)) { cp2y -= (ddy === 0 ? 1 : Math.sign(ddy)) * bend; }
        else { cp2x -= (ddx === 0 ? 1 : Math.sign(ddx)) * bend; }
    }

    // Stable jitter to avoid perfect overlap; skip for temp preview (side2 may be null)
    const sideCode = s => (s === 'top' ? 1 : s === 'bottom' ? 2 : s === 'left' ? 3 : s === 'right' ? 4 : 0);
    const c1 = sideCode(side1) | 0; const c2 = sideCode(side2) | 0;
    const pairCode = (Math.min(c1, c2) * 31 + Math.max(c1, c2)) | 0;
    const sx = Math.floor(x1 + x2) | 0;
    const sy = Math.floor(y1 + y2) | 0;
    const seed = (((sx * 73856093) ^ (sy * 19349663) ^ (pairCode * 83492791)) >>> 0) % 1000;
    const jitterFactor = seed / 1000 - 0.5;
    const jitterAmp = side2 ? Math.min(6, alongAmt * 0.2) : 0;
    const jx = jitterFactor * jitterAmp;
    const jy = -jitterFactor * jitterAmp;
    if (adx >= ady) { cp1y += jy; cp2y += jy; } else { cp1x += jx; cp2x += jx; }

    return { cp1x, cp1y, cp2x, cp2y };
}

function getEdgePathD(x1, y1, x2, y2, side1, side2) {
    const { cp1x, cp1y, cp2x, cp2y } = computeEdgeControlPoints(x1, y1, x2, y2, side1, side2);
    return `M ${x1} ${y1} C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${x2} ${y2}`;
}

// 计算边曲线在 t=0.5 处的中点（与 getEdgePathD 使用相同的控制点逻辑）
function getEdgeCurveMidpoint(edge) {
    const geometry = getEdgeRenderGeometry(edge);
    if (!geometry) return null;
    return { x: geometry.labelX, y: geometry.labelY };
}

function setupCanvasConnectionInteractions() {
    document.addEventListener('mousemove', updateConnection);
    document.addEventListener('mouseup', endConnection);

    // Clear edge selection on canvas click
    const workspace = document.getElementById('canvasWorkspace');
    if (workspace) {
        workspace.addEventListener('click', (e) => {
            // If clicking on workspace background (not on a node or edge)
            if (e.target === workspace || e.target.classList.contains('canvas-content')) {
                clearEdgeSelection();
                clearMdSelection();
            }
        });
    }
}

function selectEdge(edgeId, clientX, clientY) {
    // 清除空白栏目的选择
    clearMdSelection();

    CanvasState.selectedEdgeId = edgeId;
    renderEdges(); // Re-render to show selection state
    showEdgeToolbar(edgeId, clientX, clientY);
}

function clearEdgeSelection() {
    if (CanvasState.selectedEdgeId) {
        CanvasState.selectedEdgeId = null;
        renderEdges();
        hideEdgeToolbar();
    }
}

function showEdgeToolbar(edgeId, x, y) {
    console.log('[Edge Toolbar] showEdgeToolbar called:', edgeId);
    const edge = CanvasState.edges.find(e => e.id === edgeId);
    if (!edge) {
        console.warn('[Edge Toolbar] Edge not found:', edgeId);
        return;
    }

    const canvasContent = document.getElementById('canvasContent');
    if (!canvasContent) {
        console.warn('[Edge Toolbar] canvasContent not found');
        return;
    }

    let toolbar = document.getElementById('edge-toolbar');
    if (!toolbar) {
        console.log('[Edge Toolbar] Creating new toolbar');
        toolbar = document.createElement('div');
        toolbar.id = 'edge-toolbar';
        toolbar.className = 'md-node-toolbar edge-toolbar'; // 添加专属类名
        toolbar.style.position = 'absolute'; // 使用 absolute 定位，吸附在 canvas-content 上
        toolbar.style.zIndex = '100';
        toolbar.style.display = 'flex'; // 确保显示
        toolbar.style.opacity = '1'; // 确保可见
        toolbar.style.pointerEvents = 'auto'; // 确保可交互
        canvasContent.appendChild(toolbar); // 添加到 canvas-content 中
        console.log('[Edge Toolbar] Toolbar created and appended');
    } else {
        console.log('[Edge Toolbar] Using existing toolbar');
        toolbar.style.display = 'flex';
        toolbar.style.opacity = '1';
        toolbar.style.pointerEvents = 'auto';
    }

    // 保存当前选中的连接线 ID
    toolbar.dataset.edgeId = edgeId;

    // Multi-language support - 每次显示都更新内容以确保语言正确
    const lang = typeof currentLang !== 'undefined' ? currentLang : 'zh';
    const deleteTitle = lang === 'en' ? 'Delete' : '删除';
    const colorTitle = lang === 'en' ? 'Color' : '颜色';
    const focusTitle = lang === 'en' ? 'Locate and zoom' : '定位并放大';
    const directionTitle = lang === 'en' ? 'Line direction' : '连接线方向';
    const labelTitle = lang === 'en' ? 'Edit label' : '编辑标签';

    toolbar.innerHTML = `
        <button class="md-node-toolbar-btn" data-action="edge-delete" data-tooltip="${deleteTitle}">
            <i class="far fa-trash-alt"></i>
        </button>
        <button class="md-node-toolbar-btn" data-action="edge-color-toggle" data-tooltip="${colorTitle}">
            <i class="fas fa-palette"></i>
        </button>
        <button class="md-node-toolbar-btn" data-action="edge-focus" data-tooltip="${focusTitle}">
            <i class="fas fa-search-plus"></i>
        </button>
        <button class="md-node-toolbar-btn" data-action="edge-direction" data-tooltip="${directionTitle}">
            <i class="fas fa-arrows-alt-h"></i>
        </button>
        <button class="md-node-toolbar-btn" data-action="edge-label" data-tooltip="${labelTitle}">
            <i class="far fa-edit"></i>
        </button>
    `;

    // 更新工具栏位置（基于连接线中点，使用 canvas-content 坐标系）
    updateEdgeToolbarPosition();

    // Attach event handlers (使用事件委托，只绑定一次)
    if (!toolbar.dataset.eventsBound) {
        toolbar.addEventListener('click', (e) => {
            const btn = e.target.closest('.md-node-toolbar-btn, .md-color-chip, .md-color-picker-btn');
            if (!btn) return;
            e.preventDefault();
            e.stopPropagation();

            const currentEdgeId = toolbar.dataset.edgeId;
            const currentEdge = CanvasState.edges.find(ed => ed.id === currentEdgeId);
            if (!currentEdge) return;

            const action = btn.getAttribute('data-action');

            if (action === 'edge-delete') {
                removeEdge(currentEdgeId);
                hideEdgeToolbar();
            } else if (action === 'edge-color-toggle') {
                // 复用空白栏目的色盘弹层逻辑
                toggleEdgeColorPopover(toolbar, currentEdge, btn);
            } else if (action === 'md-color-picker-toggle') {
                // 通过委托打开原生颜色选择器
                const pop = ensureEdgeColorPopover(toolbar, currentEdge);
                const picker = pop.querySelector('.md-rgb-picker');
                const input = pop.querySelector('.md-color-input');
                if (picker && input) {
                    picker.classList.add('open');
                    setTimeout(() => input.click(), 30);
                }
            } else if (action === 'edge-focus') {
                // 复用空白栏目的定位逻辑
                locateAndZoomToEdge(currentEdgeId);
            } else if (action === 'edge-direction') {
                // 打开方向选择器
                toggleEdgeDirectionPopover(toolbar, currentEdge, btn);
            } else if (action === 'edge-label') {
                editEdgeLabel(currentEdgeId);
            } else if (action === 'md-color-preset') {
                const preset = String(btn.getAttribute('data-color') || '').trim();
                // 更新颜色历史
                const newColor = presetToHex(preset);
                if (newColor && currentEdge.colorHex) {
                    CanvasState.edgePrevColor = currentEdge.colorHex;
                }
                setEdgeColor(currentEdge, preset);
                closeEdgeColorPopover(toolbar);
            } else if (action === 'edge-direction-set') {
                const dir = String(btn.getAttribute('data-dir') || 'none');
                setEdgeDirection(currentEdge, dir);
                closeEdgeDirectionPopover(toolbar);
            } else if (action === 'edge-color-custom') {
                const customColor = btn.getAttribute('data-color');
                if (customColor) {
                    // 更新颜色历史
                    if (currentEdge.colorHex) {
                        CanvasState.edgePrevColor = currentEdge.colorHex;
                    }
                    currentEdge.color = null;
                    currentEdge.colorHex = customColor;
                    renderEdges();
                    saveTempNodes();
                    requestSidebarMenuColorSyncRefresh();
                    closeEdgeColorPopover(toolbar);
                }
            } else if (action === 'edge-color-recent') {
                // 上一次颜色
                const recentColor = btn.getAttribute('data-color') || CanvasState.edgePrevColor;
                if (recentColor) {
                    const oldColor = currentEdge.colorHex;
                    currentEdge.color = null;
                    currentEdge.colorHex = recentColor;
                    renderEdges();
                    // 交换颜色历史
                    if (oldColor) {
                        CanvasState.edgePrevColor = oldColor;
                    }
                    saveTempNodes();
                    requestSidebarMenuColorSyncRefresh();
                    closeEdgeColorPopover(toolbar);
                }
            }
        });
        toolbar.dataset.eventsBound = 'true';
    }
}

// 更新连接线工具栏位置（使用 canvas-content 坐标系）
function updateEdgeToolbarPosition() {
    const toolbar = document.getElementById('edge-toolbar');
    if (!toolbar || !toolbar.parentElement) {
        // 即使工具栏不存在，也尝试更新编辑器位置（在缩放/移动时）
        const editorOnly = document.getElementById('edge-label-editor');
        if (editorOnly && editorOnly.dataset.edgeId) {
            const edge = CanvasState.edges.find(e => e.id === editorOnly.dataset.edgeId);
            if (!edge) return;
            const start = getAnchorPosition(edge.fromNode, edge.fromSide);
            const end = getAnchorPosition(edge.toNode, edge.toSide);
            if (!start || !end) return;
            const curveMid = getEdgeCurveMidpoint(edge);
            const midX = curveMid ? curveMid.x : (start.x + end.x) / 2;
            const midY = curveMid ? curveMid.y : (start.y + end.y) / 2;
            const z = (CanvasState && CanvasState.zoom) ? CanvasState.zoom : 1;
            const offsetPx = 18;
            editorOnly.style.left = `${midX}px`;
            editorOnly.style.top = `${midY - (offsetPx / z)}px`;
            editorOnly.style.transform = `translate(-50%, -50%) scale(${(1 / z).toFixed(5)})`;
        }
        return;
    }

    const edgeId = toolbar.dataset.edgeId;
    if (!edgeId) return;

    const edge = CanvasState.edges.find(e => e.id === edgeId);
    if (!edge) return;

    const start = getAnchorPosition(edge.fromNode, edge.fromSide);
    const end = getAnchorPosition(edge.toNode, edge.toSide);

    if (!start || !end) return;

    // 工具栏定位于贝塞尔曲线中点
    const curveMid = getEdgeCurveMidpoint(edge);
    const midX = curveMid ? curveMid.x : (start.x + end.x) / 2;
    const midY = curveMid ? curveMid.y : (start.y + end.y) / 2;

    // 工具栏显示在中点上方（使用 canvas-content 坐标系），根据缩放比例调整偏移
    const z = (CanvasState && CanvasState.zoom) ? CanvasState.zoom : 1;
    toolbar.style.left = `${midX}px`;
    toolbar.style.top = `${midY - (40 / z)}px`;
    toolbar.style.transform = 'translateX(-50%)'; // 居中对齐

    // 同步更新正在编辑的输入框位置
    const editor = document.getElementById('edge-label-editor');
    if (editor && editor.dataset.edgeId === edgeId) {
        const offsetPx = 18;
        editor.style.left = `${midX}px`;
        editor.style.top = `${midY - (offsetPx / z)}px`;
        editor.style.transform = `translate(-50%, -50%) scale(${(1 / z).toFixed(5)})`;
    }
}

function hideEdgeToolbar() {
    const toolbar = document.getElementById('edge-toolbar');
    if (toolbar) {
        toolbar.style.display = 'none';
        toolbar.style.opacity = '0';
        toolbar.style.pointerEvents = 'none';
    }
}

// =============================================================================
// 连接线工具栏功能实现
// =============================================================================

// 色盘弹层逻辑（完全复用空白栏目的实现）
function ensureEdgeColorPopover(toolbar, edge) {
    let pop = toolbar.querySelector('.md-color-popover');
    if (pop) return pop;

    pop = document.createElement('div');
    pop.className = 'md-color-popover';

    // 多语言支持
    const lang = typeof currentLang !== 'undefined' ? currentLang : 'zh';
    const rgbPickerTitle = lang === 'en' ? 'RGB Color Picker' : 'RGB颜色选择器';
    const customColorTitle = lang === 'en' ? 'Select custom color' : '选择自定义颜色';
    const recentTitle = lang === 'en' ? 'Previous color' : '上一次颜色';

    // 使用 Obsidian Canvas 风格的颜色（与空白栏目完全一致）
    pop.innerHTML = `
        <span class="md-color-chip" data-action="edge-color-custom" data-color="#888888" style="background:#888888" title="${lang === 'en' ? 'Gray' : '灰色'}"></span>
        <span class="md-color-chip" data-action="edge-color-custom" data-color="#66bbff" style="background:#66bbff" title="${lang === 'en' ? 'Default Blue' : '默认蓝色'}"></span>
        <span class="md-color-chip" data-action="md-color-preset" data-color="1" style="background:#fb464c"></span>
        <span class="md-color-chip" data-action="md-color-preset" data-color="2" style="background:#e9973f"></span>
        <span class="md-color-chip" data-action="md-color-preset" data-color="3" style="background:#e0de71"></span>
        <span class="md-color-chip" data-action="md-color-preset" data-color="4" style="background:#44cf6e"></span>
        <span class="md-color-chip" data-action="md-color-preset" data-color="5" style="background:#53dfdd"></span>
        <span class="md-color-chip" data-action="md-color-preset" data-color="6" style="background:#a882ff"></span>
        <span class="md-color-divider" aria-hidden="true"></span>
        <span class="md-color-chip md-color-recent-chip" data-action="edge-color-recent" title="${recentTitle}"></span>
        <button class="md-color-chip md-color-picker-btn" data-action="md-color-picker-toggle" title="${rgbPickerTitle}">
            <svg viewBox="0 0 24 24" width="14" height="14">
                <circle cx="12" cy="12" r="10" fill="url(#rainbow-gradient-edge)" />
                <defs>
                    <linearGradient id="rainbow-gradient-edge" x1="0%" y1="0%" x2="100%" y2="100%">
                        <stop offset="0%" style="stop-color:#ff0000" />
                        <stop offset="16.67%" style="stop-color:#ff9900" />
                        <stop offset="33.33%" style="stop-color:#ffff00" />
                        <stop offset="50%" style="stop-color:#00ff00" />
                        <stop offset="66.67%" style="stop-color:#0099ff" />
                        <stop offset="83.33%" style="stop-color:#9900ff" />
                        <stop offset="100%" style="stop-color:#ff0099" />
                    </linearGradient>
                </defs>
            </svg>
        </button>
    `;

    // 上一次颜色功能
    const recentChipEl = pop.querySelector('.md-color-recent-chip');
    const resolveHistoryColor = (value) => {
        const normalized = normalizeHexColor(value || '');
        return normalized ? `#${normalized}` : getEdgeDefaultColor();
    };
    const syncHistoryChip = (value) => {
        if (!recentChipEl) return;
        const safe = resolveHistoryColor(value);
        recentChipEl.dataset.color = safe;
        recentChipEl.style.backgroundColor = safe;
    };
    // 初始化上一次颜色
    syncHistoryChip(CanvasState.edgePrevColor || getEdgeDefaultColor());

    // RGB选择器UI（显示在色盘上方，与空白栏目完全一致）
    const rgbPicker = document.createElement('div');
    rgbPicker.className = 'md-rgb-picker';
    rgbPicker.innerHTML = `
        <input class="md-color-input" type="color" value="${edge.colorHex || getEdgeDefaultColor()}" title="${customColorTitle}" />
    `;
    pop.appendChild(rgbPicker);

    // 彩色圆盘按钮点击事件 - 切换RGB选择器显示
    const pickerBtn = pop.querySelector('.md-color-picker-btn');
    const colorInput = rgbPicker.querySelector('.md-color-input');

    pickerBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        const isOpen = rgbPicker.classList.contains('open');
        if (isOpen) {
            rgbPicker.classList.remove('open');
        } else {
            rgbPicker.classList.add('open');
            // 延迟触发点击，确保UI已显示
            setTimeout(() => colorInput.click(), 50);
        }
    });

    // 自定义颜色变化
    colorInput.addEventListener('input', (ev) => {
        setEdgeColor(edge, ev.target.value);
    });

    colorInput.addEventListener('change', () => {
        rgbPicker.classList.remove('open');
    });

    toolbar.appendChild(pop);
    return pop;
}

function toggleEdgeColorPopover(toolbar, edge, anchorBtn) {
    const pop = ensureEdgeColorPopover(toolbar, edge);
    const isOpen = pop.classList.contains('open');
    if (isOpen) {
        closeEdgeColorPopover(toolbar);
        return;
    }
    pop.classList.add('open');
    // 监听外部点击关闭
    const onDoc = (e) => {
        if (!toolbar.contains(e.target)) {
            closeEdgeColorPopover(toolbar);
            document.removeEventListener('mousedown', onDoc, true);
        }
    };
    document.addEventListener('mousedown', onDoc, true);
}

function closeEdgeColorPopover(toolbar) {
    const pop = toolbar.querySelector('.md-color-popover:not(.md-direction-popover)');
    if (pop) pop.classList.remove('open');
}

function setEdgeColor(edge, presetOrHex) {
    if (!edge) return;

    // 支持预设编号或十六进制颜色
    const isPreset = /^[1-6]$/.test(String(presetOrHex));
    if (isPreset) {
        edge.color = String(presetOrHex);
        edge.colorHex = presetToHex(edge.color);
    } else if (typeof presetOrHex === 'string' && presetOrHex.startsWith('#')) {
        edge.color = null;
        edge.colorHex = presetOrHex;
    }

    renderEdges();
    saveTempNodes();
    requestSidebarMenuColorSyncRefresh();
}

// 方向弹层（与色盘风格一致）
function ensureEdgeDirectionPopover(toolbar, edge) {
    let pop = toolbar.querySelector('.md-direction-popover');
    if (pop) return pop;
    pop = document.createElement('div');
    pop.className = 'md-color-popover md-direction-popover';
    const lang = typeof currentLang !== 'undefined' ? currentLang : 'zh';
    const noneText = lang === 'en' ? 'None' : '无方向';
    const singleText = lang === 'en' ? 'Single' : '单向';
    const bothText = lang === 'en' ? 'Both' : '双向';
    pop.innerHTML = `
        <span class="md-color-chip dir-chip" data-action="edge-direction-set" data-dir="none" title="${noneText}"><i class="fas fa-minus"></i></span>
        <span class="md-color-chip dir-chip" data-action="edge-direction-set" data-dir="forward" title="${singleText}"><i class="fas fa-long-arrow-alt-right"></i></span>
        <span class="md-color-chip dir-chip" data-action="edge-direction-set" data-dir="both" title="${bothText}"><i class="fas fa-arrows-alt-h"></i></span>
    `;
    toolbar.appendChild(pop);
    return pop;
}

function toggleEdgeDirectionPopover(toolbar, edge, anchorBtn) {
    const pop = ensureEdgeDirectionPopover(toolbar, edge);
    const isOpen = pop.classList.contains('open');
    // 关闭色盘，避免重叠
    closeEdgeColorPopover(toolbar);
    if (isOpen) {
        pop.classList.remove('open');
        return;
    }
    pop.classList.add('open');
    const onDoc = (e) => {
        if (!toolbar.contains(e.target)) {
            closeEdgeDirectionPopover(toolbar);
            document.removeEventListener('mousedown', onDoc, true);
        }
    };
    document.addEventListener('mousedown', onDoc, true);
}

function closeEdgeDirectionPopover(toolbar) {
    const pop = toolbar.querySelector('.md-direction-popover');
    if (pop) pop.classList.remove('open');
}

function setEdgeDirection(edge, dir) {
    if (!edge) return;
    const v = (dir === 'forward' || dir === 'both') ? dir : 'none';
    edge.direction = v;
    renderEdges();
    saveTempNodes();
}

// 定位并放大到连接线（复用空白栏目的定位逻辑）
function locateAndZoomToEdge(edgeId, targetZoom = 1.2) {
    const edge = CanvasState.edges.find(e => e.id === edgeId);
    const workspace = document.getElementById('canvasWorkspace');
    if (!edge || !workspace) return;

    const start = getAnchorPosition(edge.fromNode, edge.fromSide);
    const end = getAnchorPosition(edge.toNode, edge.toSide);
    if (!start || !end) return;

    // 先调整缩放（与空白栏目逻辑一致）
    const zoom = clampCanvasZoom(Math.max(CanvasState.zoom || 1, targetZoom));
    if (zoom !== CanvasState.zoom) {
        const rect = workspace.getBoundingClientRect();
        setCanvasZoom(zoom, rect.left + rect.width / 2, rect.top + rect.height / 2, { recomputeBounds: true });
    }

    // 计算连接线中心点
    const centerX = (start.x + end.x) / 2;
    const centerY = (start.y + end.y) / 2;

    // 平移到中心点（与空白栏目逻辑一致）
    const workspaceWidth = workspace.clientWidth;
    const workspaceHeight = workspace.clientHeight;
    CanvasState.panOffsetX = workspaceWidth / 2 - centerX * CanvasState.zoom;
    CanvasState.panOffsetY = workspaceHeight / 2 - centerY * CanvasState.zoom;

    updateCanvasScrollBounds();
    savePanOffsetThrottled();
}

// 切换连接线方向（交换起点和终点）
function toggleEdgeDirection(edgeId) {
    const edge = CanvasState.edges.find(e => e.id === edgeId);
    if (!edge) return;

    // 交换起点和终点
    const tempNode = edge.fromNode;
    const tempSide = edge.fromSide;
    edge.fromNode = edge.toNode;
    edge.fromSide = edge.toSide;
    edge.toNode = tempNode;
    edge.toSide = tempSide;

    renderEdges();
    saveTempNodes();

    console.log('[Canvas] 切换连接线方向:', edgeId);
}

// 编辑连接线标签
function editEdgeLabel(edgeId) {
    // 向后兼容：按钮调用改为就地编辑
    startEdgeLabelInlineEdit(edgeId);
}

// 就地编辑连接线标签（不再使用 prompt）
function startEdgeLabelInlineEdit(edgeId) {
    const edge = CanvasState.edges.find(e => e.id === edgeId);
    const svg = document.querySelector('.canvas-edges');
    if (!edge || !svg) return;

    // 清除已有的编辑器
    const existingFo = svg.querySelector(`foreignObject[data-edge-id="${edgeId}"]`);
    if (existingFo) { try { existingFo.remove(); } catch (_) { } }

    // 移除原文字（若存在）
    const textEl = svg.querySelector(`text.canvas-edge-label[data-edge-id="${edgeId}"]`);
    if (textEl) { try { textEl.remove(); } catch (_) { } }

    // 计算放置位置
    const start = getAnchorPosition(edge.fromNode, edge.fromSide);
    const end = getAnchorPosition(edge.toNode, edge.toSide);
    if (!start || !end) return;
    const mid = getEdgeCurveMidpoint(edge) || { x: (start.x + end.x) / 2, y: (start.y + end.y) / 2 };

    // 使用探针测量当前文本尺寸（用户单位）
    const probe = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    probe.setAttribute('class', 'canvas-edge-label');
    probe.textContent = edge.label || '';
    probe.setAttribute('x', mid.x);
    probe.setAttribute('y', mid.y);
    probe.setAttribute('text-anchor', 'middle');
    probe.setAttribute('dominant-baseline', 'middle');
    svg.appendChild(probe);
    let textW = 30, textH = 16;
    try {
        textW = Math.max(30, probe.getComputedTextLength ? probe.getComputedTextLength() : 30);
        const bb = probe.getBBox ? probe.getBBox() : null;
        textH = Math.max(16, bb && bb.height ? Math.ceil(bb.height) : 16);
    } catch (_) { }
    try { probe.remove(); } catch (_) { }

    const fo = document.createElementNS('http://www.w3.org/2000/svg', 'foreignObject');
    fo.setAttribute('data-edge-id', edgeId);
    fo.setAttribute('class', 'edge-label-fo');
    fo.setAttribute('x', (mid.x - textW / 2).toString());
    fo.setAttribute('y', (mid.y - textH / 2).toString());
    fo.setAttribute('width', (textW).toString());
    fo.setAttribute('height', (textH).toString());
    fo.style.pointerEvents = 'all';

    const div = document.createElement('div');
    div.setAttribute('xmlns', 'http://www.w3.org/1999/xhtml');
    div.className = 'edge-label-inline';
    div.contentEditable = 'true';
    div.textContent = edge.label || '';
    div.style.whiteSpace = 'nowrap';
    div.style.padding = '0';
    div.style.margin = '0';
    div.style.background = 'transparent';
    div.style.outline = 'none';
    div.style.border = 'none';
    div.style.cursor = 'text';
    div.style.userSelect = 'text';
    div.style.WebkitUserSelect = 'text';
    div.style.minWidth = 'max-content'; // 确保内容完全显示
    div.style.width = 'max-content'; // 自动适应内容宽度
    // 字体样式与SVG文本一致
    div.style.fontSize = '16px';
    div.style.fontWeight = '500';
    const edgeColor = edge.colorHex || presetToHex(edge.color) || '';
    if (edgeColor) div.style.color = edgeColor;

    // 挖空矩形（如未存在则创建）
    let rect = svg.querySelector(`rect.canvas-edge-label-bg[data-edge-id="${edgeId}"]`);
    if (!rect) {
        rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
        rect.setAttribute('class', 'canvas-edge-label-bg');
        rect.setAttribute('data-edge-id', edgeId);
        rect.setAttribute('rx', '4');
        rect.setAttribute('ry', '4');
        rect.style.pointerEvents = 'none';
        try {
            const ws = document.getElementById('canvasWorkspace');
            const bg = ws ? getComputedStyle(ws).backgroundColor : getComputedStyle(document.querySelector('.canvas-main-container')).backgroundColor;
            rect.setAttribute('fill', bg || '#fff');
        } catch (_) { rect.setAttribute('fill', '#fff'); }
        svg.appendChild(rect);
    }

    const layout = () => {
        const z = (CanvasState && CanvasState.zoom) ? CanvasState.zoom : 1;
        // 使用 scrollWidth 获取实际内容宽度，而不是被截断的宽度
        const r = div.getBoundingClientRect();
        const actualWidth = Math.max(r.width, div.scrollWidth);
        const w = Math.max(12, actualWidth / z);
        const h = Math.max(14, r.height / z);
        fo.setAttribute('x', (mid.x - w / 2).toString());
        fo.setAttribute('y', (mid.y - h / 2).toString());
        fo.setAttribute('width', w.toString());
        fo.setAttribute('height', h.toString());
        rect.setAttribute('x', (mid.x - (w / 2) - 4).toString());
        rect.setAttribute('y', (mid.y - (h / 2) - 2).toString());
        rect.setAttribute('width', (w + 8).toString());
        rect.setAttribute('height', (h + 4).toString());
    };

    const apply = () => {
        const val = (div.textContent || '').trim();
        edge.label = val;
        try { fo.remove(); } catch (_) { }
        renderEdges();
        saveTempNodes();
    };
    const cancel = () => {
        try { fo.remove(); } catch (_) { }
        renderEdges();
    };

    div.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') { e.preventDefault(); apply(); }
        else if (e.key === 'Escape') { e.preventDefault(); cancel(); }
    });
    div.addEventListener('input', () => layout());
    div.addEventListener('blur', () => apply());
    ['mousedown', 'click', 'dblclick'].forEach(evt => div.addEventListener(evt, ev => ev.stopPropagation()));

    fo.appendChild(div);
    svg.appendChild(fo);
    requestAnimationFrame(() => {
        layout();
        div.focus();
        try {
            const range = document.createRange();
            range.selectNodeContents(div);
            range.collapse(false);
            const sel = window.getSelection();
            sel.removeAllRanges();
            sel.addRange(range);
        } catch (_) { }
    });
}

